'use client';
import { builder, Builder } from '@builder.io/sdk';
import { Content } from '@builder.io/sdk-react';
import dynamic from 'next/dynamic';

builder.init('BUILDER_API_KEY');

// Dynamically import components
const Header = dynamic(() => import('./sections/Header'));
const Footer = dynamic(() => import('./sections/Footer'));
const Hero = dynamic(() => import('./sections/Hero'));
const Faq = dynamic(() => import('./sections/Faq'));
const ImageWithParagraph = dynamic(() => import('./sections/ImageWithParagraph'));
const Logos = dynamic(() => import('./sections/Logos'));
const Testimonials = dynamic(() => import('./sections/Testimonials'));
const BlogPosts = dynamic(() => import('./sections/BlogPosts'));

// Re-export RenderBuilderContent for use in the page component
export { RenderBuilderContent };

// Register Header
Builder.registerComponent(Header, {
  name: 'Header',
  inputs: [
    {
      name: 'navItems',
      type: 'list',
      subFields: [
        { name: 'label', type: 'string', required: true },
        { name: 'href', type: 'url', required: true },
      ],
    },
    {
      name: 'buttons',
      type: 'list',
      subFields: [
        { name: 'text', type: 'string', required: true },
        { name: 'href', type: 'url', required: true },
        { name: 'variant', type: 'string', enum: ['Normal', 'Reverse'], defaultValue: 'Normal' },
      ],
    },
  ],
});

// Register Footer
Builder.registerComponent(Footer, {
  name: 'Footer',
  inputs: [
    {
      name: 'sections',
      type: 'list',
      subFields: [
        { name: 'label', type: 'string' },
        {
          name: 'items',
          type: 'list',
          subFields: [
            { name: 'label', type: 'string' },
            { name: 'href', type: 'url' },
          ],
        },
      ],
    },
  ],
});

// Register Hero
Builder.registerComponent(Hero, {
  name: 'Hero',
  inputs: [
    { name: 'title', type: 'string', defaultValue: 'Hero Title' },
    { name: 'description', type: 'richText', defaultValue: 'Hero Description' },
    { name: 'image', type: 'file', allowedFileTypes: ['jpeg', 'png', 'svg'] },
    { name: 'placement', type: 'string', enum: ['left', 'right'], defaultValue: 'left' },
    {
      name: 'cta',
      type: 'list',
      subFields: [
        { name: 'text', type: 'string', defaultValue: 'Click me' },
        { name: 'href', type: 'url', defaultValue: '/' },
        { name: 'variant', type: 'string', enum: ['Normal', 'Reverse'], defaultValue: 'Normal' },
      ],
    },
  ],
});

// Register FAQ
Builder.registerComponent(Faq, {
  name: 'FAQ',
  inputs: [
    { name: 'title', type: 'string', defaultValue: 'Frequently Asked Questions' },
    { name: 'description', type: 'string' },
    {
      name: 'questions',
      type: 'list',
      subFields: [
        { name: 'question', type: 'string' },
        { name: 'answer', type: 'richText' },
      ],
    },
  ],
});

// Register ImageWithParagraph
Builder.registerComponent(ImageWithParagraph, {
  name: 'Image With Paragraph',
  inputs: [
    { name: 'title', type: 'string' },
    { name: 'text', type: 'richText' },
    { name: 'image', type: 'file', allowedFileTypes: ['jpeg', 'png', 'svg'] },
    { name: 'placement', type: 'string', enum: ['left', 'right'], defaultValue: 'left' },
  ],
});

// Register Logos
Builder.registerComponent(Logos, {
  name: 'Logos',
  inputs: [
    { name: 'title', type: 'string' },
    {
      name: 'logos',
      type: 'list',
      subFields: [
        { name: 'src', type: 'file', allowedFileTypes: ['jpeg', 'png', 'svg'] },
        { name: 'alt', type: 'string' },
      ],
    },
  ],
});

// Register Testimonials
Builder.registerComponent(Testimonials, {
  name: 'Testimonials',
  inputs: [
    { name: 'title', type: 'string' },
    {
      name: 'testimonials',
      type: 'list',
      subFields: [
        { name: 'text', type: 'longText' },
        { name: 'author', type: 'string' },
        { name: 'avatar', type: 'file', allowedFileTypes: ['jpeg', 'png'] },
      ],
    },
  ],
});

// Register BlogPosts
Builder.registerComponent(BlogPosts, {
  name: 'Blog Posts',
  inputs: [
    { name: 'title', type: 'string' },
    // In a real app, you would fetch posts dynamically.
    // This allows manual entry for static pages.
    {
      name: 'posts',
      type: 'list',
      subFields: [
        { name: 'slug', type: 'string' },
        { name: 'title', type: 'string' },
        { name: 'excerpt', type: 'longText' },
        { name: 'imageUrl', type: 'file' },
        { name: 'author', type: 'string' },
        { name: 'date', type: 'date' },
      ],
    },
  ],
});
